    if (!box || !wrap || typeof window.cwRenderLayoutSummary !== 'function') { return null; }
    var prevLayout = getPendingLayout();           /* may throw → caller's safe() */
    var prevBox = box.innerHTML;
    var prevWrap = wrap.style.display;
