  function catIcon(key) { return isValidCategory(key) ? CAT_BY_KEY[key].icon : '📄'; }

  /* ---------- data access (pure - unit-testable) ---------- */
  function listOf(p) { return (p && Array.isArray(p.outsideRecords)) ? p.outsideRecords : []; }

