      var line = roster.length + ' patient' + (roster.length === 1 ? '' : 's') + ' on the ' + (mo.value || thisMonth()) + ' schedule; ' + need + ' still need a chart pull (~' + Math.ceil(need * 45 / 60) + ' min).';
