        /* fallback: if search-open never answers, try the bare read anyway */
        setTimeout(function () {
          if (GATE.phase === 1 && GATE.want) {
            GATE.phase = 2;
            nativePost({ source: 'mls-app', type: 'mlsAppReadChart', __cfxBare: 1 }, location.origin);
          }
        }, 25000);
