    var ta = $('ez3Note');
    if (ta) {
      ta.value = noteText();
      ta.addEventListener('input', function () {
        var n = $('noteBox');
        if (n) { n.value = ta.value; try { n.dispatchEvent(new Event('input', { bubbles: true })); } catch (e) {} }
      });
    }
