        if (!rows.length) { P.dayStatus[dayKey] = { status: 'empty' }; P.emptyDays.push(dayKey); plog(pd + ': no appointments' + (filter !== 'all' ? (' for ' + filter) : '') + ' — empty day, moving on.'); pCounts(); return 'empty'; }
        P.found += rows.length;
