      'color:#eef4ff;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;overflow:hidden;',
      'box-shadow:0 14px 44px rgba(10,24,60,.35);border:1px solid rgba(120,150,240,.18);}',
    '#mlsEz3 *{box-sizing:border-box;}',
